import math

def newman_prime(n):
    def nsw_number(k):
        if k == 1:
            return 1
        elif k == 2:
            return 7
        else:
            return 2 * (nsw_number(k - 1) + nsw_number(k - 2)) + 1

    count = 0
    k = 1
    while True:
        num = nsw_number(k)
        if is_prime(num):
            count += 1
            if count == n:
                return num
        k += 1

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True
